use serde_json::{Value, json};

use crate::{BucketSummaryContract, ClassificationContract, ContractError, ExtractionContract};

/// A strict Structured Outputs contract accepted at the LLM boundary.
///
/// Each implementation exposes the same JSON Schema currently generated by
/// the Python OpenAI SDK for the matching Pydantic model, then validates the
/// returned JSON through the existing Rust contract adapter.
pub trait StructuredOutputContract: Sized {
    const SCHEMA_NAME: &'static str;

    fn strict_json_schema() -> Value;

    fn from_structured_value(value: Value) -> Result<Self, ContractError>;
}

impl StructuredOutputContract for ClassificationContract {
    const SCHEMA_NAME: &'static str = "ClassificationResult";

    fn strict_json_schema() -> Value {
        json!({
            "additionalProperties": false,
            "description": "The routing decision for one user input.",
            "properties": {
                "action": {
                    "description": "Append to an existing bucket, create one, or ask the user.",
                    "enum": ["append_existing", "create_new", "ask_user"],
                    "title": "Action",
                    "type": "string"
                },
                "bucket_id": {
                    "anyOf": [{"type": "string"}, {"type": "null"}],
                    "description": "Existing bucket ID when action is append_existing.",
                    "title": "Bucket Id"
                },
                "bucket_type": {
                    "anyOf": [
                        {
                            "enum": [
                                "idea",
                                "task",
                                "incident",
                                "experiment",
                                "decision",
                                "meeting",
                                "knowledge",
                                "draft"
                            ],
                            "type": "string"
                        },
                        {"type": "null"}
                    ],
                    "description": "Selected type for a new bucket or the matched bucket type.",
                    "title": "Bucket Type"
                },
                "candidate_bucket_ids": {
                    "description": "Likely bucket IDs to present when asking the user.",
                    "items": {"type": "string"},
                    "title": "Candidate Bucket Ids",
                    "type": "array"
                },
                "confidence": {
                    "description": "Confidence score between 0 and 1.",
                    "title": "Confidence",
                    "type": "number"
                },
                "question": {
                    "anyOf": [{"type": "string"}, {"type": "null"}],
                    "description": "Clarifying question when action is ask_user.",
                    "title": "Question"
                },
                "reason": {
                    "description": "Short evidence-based explanation for the routing decision.",
                    "title": "Reason",
                    "type": "string"
                },
                "should_ask_user": {
                    "default": false,
                    "description": "Whether user confirmation is required before persistence.",
                    "title": "Should Ask User",
                    "type": "boolean"
                },
                "title": {
                    "anyOf": [{"type": "string"}, {"type": "null"}],
                    "description": "Concise new bucket title when action is create_new.",
                    "title": "Title"
                }
            },
            "required": [
                "action",
                "bucket_id",
                "bucket_type",
                "title",
                "confidence",
                "reason",
                "should_ask_user",
                "question",
                "candidate_bucket_ids"
            ],
            "title": "ClassificationResult",
            "type": "object"
        })
    }

    fn from_structured_value(value: Value) -> Result<Self, ContractError> {
        Self::from_value(value)
    }
}

impl StructuredOutputContract for ExtractionContract {
    const SCHEMA_NAME: &'static str = "ExtractionResult";

    fn strict_json_schema() -> Value {
        json!({
            "$defs": {
                "TimelineEventExtract": {
                    "additionalProperties": false,
                    "description": "A time expression and event extracted from the raw input.",
                    "properties": {
                        "event_time": {
                            "anyOf": [{"type": "string"}, {"type": "null"}],
                            "description": "Original time expression, or null when no time is stated.",
                            "title": "Event Time"
                        },
                        "text": {
                            "description": "What happened at that time.",
                            "title": "Text",
                            "type": "string"
                        }
                    },
                    "required": ["event_time", "text"],
                    "title": "TimelineEventExtract",
                    "type": "object"
                }
            },
            "additionalProperties": false,
            "description": "Structured work-memory facts extracted from one raw entry.",
            "properties": {
                "decisions": {
                    "description": "Decisions or actions already taken.",
                    "items": {"type": "string"},
                    "title": "Decisions",
                    "type": "array"
                },
                "entities": {
                    "description": "Important systems, APIs, customers, projects, or components.",
                    "items": {"type": "string"},
                    "title": "Entities",
                    "type": "array"
                },
                "evidences": {
                    "description": "Logs, metrics, observations, test results, or user feedback.",
                    "items": {"type": "string"},
                    "title": "Evidences",
                    "type": "array"
                },
                "hypotheses": {
                    "description": "Unverified explanations or claims that still need validation.",
                    "items": {"type": "string"},
                    "title": "Hypotheses",
                    "type": "array"
                },
                "summary": {
                    "description": "Faithful one-sentence summary of the input.",
                    "title": "Summary",
                    "type": "string"
                },
                "tags": {
                    "description": "Short labels useful for keyword search.",
                    "items": {"type": "string"},
                    "title": "Tags",
                    "type": "array"
                },
                "timeline_events": {
                    "description": "Events with their original time expressions when available.",
                    "items": {"$ref": "#/$defs/TimelineEventExtract"},
                    "title": "Timeline Events",
                    "type": "array"
                },
                "todos": {
                    "description": "Concrete actions that still need to be completed.",
                    "items": {"type": "string"},
                    "title": "Todos",
                    "type": "array"
                }
            },
            "required": [
                "summary",
                "todos",
                "evidences",
                "timeline_events",
                "decisions",
                "hypotheses",
                "entities",
                "tags"
            ],
            "title": "ExtractionResult",
            "type": "object"
        })
    }

    fn from_structured_value(value: Value) -> Result<Self, ContractError> {
        Self::from_value(value)
    }
}

impl StructuredOutputContract for BucketSummaryContract {
    const SCHEMA_NAME: &'static str = "BucketSummaryResult";

    fn strict_json_schema() -> Value {
        json!({
            "additionalProperties": false,
            "description": "A compact rolling summary for a long-lived Bucket.",
            "properties": {
                "summary": {
                    "title": "Summary",
                    "type": "string"
                }
            },
            "required": ["summary"],
            "title": "BucketSummaryResult",
            "type": "object"
        })
    }

    fn from_structured_value(value: Value) -> Result<Self, ContractError> {
        Self::from_value(value)
    }
}
